import json, sys
from pathlib import Path
from collections import Counter

def summarize(path):
    with Path(path).open("rb") as stream:
        data = stream.read(1_048_577)
    if len(data) > 1_048_576:
        raise ValueError("Input exceeds 1 MiB")
    counts = Counter()
    total = 0
    for number, line in enumerate(data.decode("utf-8").splitlines(), 1):
        if not line.strip():
            continue
        row = json.loads(line)
        if not isinstance(row, dict) or type(row.get("status")) is not int or not 100 <= row["status"] <= 599:
            raise ValueError(f"Invalid status on line {number}")
        counts[str(row["status"])] += 1
        total += 1
    return {"records": total, "statuses": dict(sorted(counts.items()))}

if __name__ == "__main__":
    if len(sys.argv) != 2:
        print("Usage: python3 log_summary.py sample.jsonl", file=sys.stderr)
        sys.exit(2)
    try:
        print(json.dumps(summarize(sys.argv[1]), sort_keys=True))
    except (OSError, ValueError) as error:
        print(f"Cannot summarize: {error}", file=sys.stderr)
        sys.exit(1)

import {open} from "node:fs/promises";

async function summarize(path) {
  const handle = await open(path, "r");
  const buffer = Buffer.alloc(1_048_577);
  let used = 0;
  try {
    while (used < buffer.length) {
      const {bytesRead} = await handle.read(buffer, used, buffer.length - used, null);
      if (!bytesRead) break;
      used += bytesRead;
    }
  } finally { await handle.close(); }
  if (used > 1_048_576) throw new Error("Input exceeds 1 MiB");
  const text = new TextDecoder("utf-8", {fatal:true}).decode(buffer.subarray(0, used));
  const counts = new Map();
  let records = 0;
  for (const [index, line] of text.split(/\r?\n/).entries()) {
    if (!line.trim()) continue;
    const row = JSON.parse(line);
    if (!row || Array.isArray(row) || typeof row !== "object" || !Number.isInteger(row.status) || row.status < 100 || row.status > 599) {
      throw new Error(`Invalid status on line ${index + 1}`);
    }
    const status = String(row.status);
    counts.set(status, (counts.get(status) ?? 0) + 1);
    records += 1;
  }
  return {records, statuses: Object.fromEntries([...counts].sort())};
}

if (process.argv.length !== 3) {
  console.error("Usage: node log_summary.mjs sample.jsonl");
  process.exitCode = 2;
} else {
  try { console.log(JSON.stringify(await summarize(process.argv[2]))); }
  catch (error) { console.error(`Cannot summarize: ${error.message}`); process.exitCode = 1; }
}

import http.client, json, sys

def inspect(port):
    connection = http.client.HTTPConnection("127.0.0.1", port, timeout=3)
    try:
        connection.request("HEAD", "/")
        response = connection.getresponse()
        names = ["content-type", "content-security-policy", "x-content-type-options"]
        return {"status": response.status, "headers": {name: response.getheader(name) for name in names}}
    finally:
        connection.close()

if __name__ == "__main__":
    try:
        if len(sys.argv) > 2:
            raise ValueError("Usage: python3 local_headers.py [port]")
        port = int(sys.argv[1]) if len(sys.argv) == 2 else 8877
        if not 1 <= port <= 65535:
            raise ValueError("Port must be 1..65535")
        print(json.dumps(inspect(port), sort_keys=True))
    except (ValueError, OSError, http.client.HTTPException) as error:
        print(f"Cannot inspect: {error}", file=sys.stderr)
        sys.exit(1)

import http from "node:http";

function inspect(port) {
  return new Promise((resolve, reject) => {
    const request = http.request({hostname:"127.0.0.1", port, path:"/", method:"HEAD", maxHeaderSize:16384}, response => {
      const names = ["content-type", "content-security-policy", "x-content-type-options"];
      const headers = Object.fromEntries(names.map(name => [name, response.headers[name] ?? null]));
      response.resume();
      resolve({status:response.statusCode, headers});
    });
    const timer = setTimeout(() => request.destroy(new Error("Three-second deadline exceeded")), 3000);
    request.on("close", () => clearTimeout(timer));
    request.on("error", reject);
    request.end();
  });
}

try {
  if (process.argv.length > 3) throw new Error("Usage: node local_headers.mjs [port]");
  const raw = process.argv[2] ?? "8877";
  if (!/^[0-9]+$/.test(raw)) throw new Error("Port must contain digits");
  const port = Number(raw);
  if (!Number.isInteger(port) || port < 1 || port > 65535) throw new Error("Port must be 1..65535");
  console.log(JSON.stringify(await inspect(port)));
} catch (error) {
  console.error(`Cannot inspect: ${error.message}`);
  process.exitCode = 1;
}
